function spreadOrders(n: number, sick: number[]): number {
  const MOD = 1000000007, full = (1 << n) - 1;
  const memo = new Map<number, number>();
  const count = (mask: number): number => {
    if (mask === full) return 1;
    const hit = memo.get(mask);
    if (hit !== undefined) return hit;
    let total = 0;
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) continue;
      const near = (i > 0 && (mask >> (i - 1)) & 1) || (i < n - 1 && (mask >> (i + 1)) & 1);
      if (near) total = (total + count(mask | (1 << i))) % MOD;
    }
    memo.set(mask, total);
    return total;
  };
  let start = 0;
  for (const s of sick) start |= 1 << s;
  return count(start);
}

