function spreadOrders(n: number, sick: number[]): number {
  const MOD = 1000000007n;
  const pow = (b: bigint, e: bigint) => {
    let r = 1n; b %= MOD;
    for (; e > 0n; e >>= 1n, b = b * b % MOD) if (e & 1n) r = r * b % MOD;
    return r;
  };
  const fact: bigint[] = [1n];
  for (let i = 1; i <= n; i++) fact.push(fact[i - 1] * BigInt(i) % MOD);
  const inv = (x: bigint) => pow(x, MOD - 2n); // Fermat: MOD is prime
  const m = n - sick.length;
  let ans = fact[m];
  ans = ans * inv(fact[sick[0]]) % MOD;                       // left end gap
  ans = ans * inv(fact[n - 1 - sick[sick.length - 1]]) % MOD; // right end gap
  for (let i = 1; i < sick.length; i++) {
    const g = sick[i] - sick[i - 1] - 1;
    if (g === 0) continue;
    ans = ans * inv(fact[g]) % MOD * pow(2n, BigInt(g - 1)) % MOD;
  }
  return Number(ans);
}

