function spreadOrders(n: number, sick: number[]): number {
  const MOD = 1000000007n;
  const pow = (b: bigint, e: number) => {
    let r = 1n;
    for (; e > 0; e >>= 1, b = b * b % MOD) if (e & 1) r = r * b % MOD;
    return r;
  };
  const fact: bigint[] = [1n];
  for (let i = 1; i <= n; i++) fact.push(fact[i - 1] * BigInt(i) % MOD);
  const invFact: bigint[] = new Array(n + 1);
  invFact[n] = pow(fact[n], 1000000005);
  for (let i = n; i > 0; i--) invFact[i - 1] = invFact[i] * BigInt(i) % MOD;
  const choose = (a: number, b: number) => fact[a] * invFact[b] % MOD * invFact[a - b] % MOD;
  const gaps: [number, boolean][] = [[sick[0], false], [n - 1 - sick[sick.length - 1], false]];
  for (let i = 1; i < sick.length; i++) gaps.push([sick[i] - sick[i - 1] - 1, true]);
  let ans = 1n, placed = 0;
  for (const [g, inner] of gaps) {
    if (g === 0) continue;
    ans = ans * choose(placed + g, g) % MOD;
    if (inner) ans = ans * pow(2n, g - 1) % MOD;
    placed += g;
  }
  return Number(ans);
}

